def spans(tags):            # BIO2 tags to (type, start, end)
    out, cur = [], None
    for i, t in enumerate(tags):
        if t == "O":
            if cur: out.append(cur)
            cur = None
        elif t[0] == "B":
            if cur: out.append(cur)
            cur = [t[2:], i, i]
        else:                        # t[0] == "I"
            if cur and cur[0] == t[2:]:
                cur[2] = i           # extend the open span
            else:                    # I after O, or a type switch
                cur = [t[2:], i, i]  # conlleval opens a new span
    if cur: out.append(cur)
    return out

